"""Demo: unsigned positivity obstruction for the trefoil polynomial."""
from typing import Dict

Coeffs = Dict[int, int]
TREFOIL: Coeffs = {1: 1, 0: -1, -1: 1}

def is_nonneg(c: Coeffs) -> bool:
    return all(v >= 0 for v in c.values())

def can_be_unsigned_count(c: Coeffs) -> bool:
    """An unsigned area generating function must have non-negative coefficients."""
    return is_nonneg(c)

if __name__ == "__main__":
    print("Trefoil:", TREFOIL)
    print("t^0 coefficient:", TREFOIL[0])
    print("Could be an unsigned lattice-path count?", can_be_unsigned_count(TREFOIL))
    print("=> No: a count cannot be -1.")

"""Demo: signed state sum reproduces the trefoil polynomial."""
from dataclasses import dataclass
from typing import Dict, List, Sequence

@dataclass(frozen=True)
class State:
    area: int
    sign: int  # +1 or -1

def signed_gf(states: Sequence[State]) -> Dict[int, int]:
    out: Dict[int, int] = {}
    for s in states:
        out[s.area] = out.get(s.area, 0) + s.sign
    return out

if __name__ == "__main__":
    states: List[State] = [State(1, +1), State(0, -1), State(-1, +1)]
    gf = signed_gf(states)
    print("signed state sum:", gf)
    print("equals t - 1 + t^{-1}?", gf == {1: 1, 0: -1, -1: 1})

"""Demo: monotone lattice paths count C(2n,n) and Kruskal-Katona shadow."""
from itertools import combinations
from math import comb
from typing import Iterable, List, Tuple

def lattice_paths(n: int) -> List[Tuple[int, ...]]:
    return [tuple(c) for c in combinations(range(2 * n), n)]

def shadow(family: Iterable[Tuple[int, ...]]) -> List[Tuple[int, ...]]:
    out = set()
    for s in family:
        for i in range(len(s)):
            out.add(s[:i] + s[i + 1:])
    return sorted(out)

if __name__ == "__main__":
    for n in range(1, 6):
        print(f"n={n}: paths={len(lattice_paths(n))}, C(2n,n)={comb(2*n, n)}")
    n, k = 3, 4
    fam = lattice_paths(n)[:comb(k, n)]
    print(f"family={len(fam)}, shadow={len(shadow(fam))}, bound C(k,n-1)={comb(k, n-1)}")

