from typing import Dict

def unsigned_realizable(c: Dict[int, int]) -> bool:
    """True iff every coefficient is non-negative (necessary and
    sufficient for realizability as an unsigned area GF)."""
    return all(v >= 0 for v in c.values())

from dataclasses import dataclass
from typing import Dict, List

@dataclass(frozen=True)
class State:
    area: int
    sign: int

def realize_signed(c: Dict[int, int]) -> List[State]:
    states: List[State] = []
    for k, v in c.items():
        if v == 0:
            continue
        s = 1 if v > 0 else -1
        states.extend(State(area=k, sign=s) for _ in range(abs(v)))
    return states

