from itertools import combinations
from math import comb
from typing import Iterable, List, Tuple

def shadow(family: Iterable[Tuple[int, ...]]) -> List[Tuple[int, ...]]:
    out = set()
    for S in family:
        for i in range(len(S)):
            out.add(S[:i] + S[i + 1:])
    return sorted(out)

def kk_bound_holds(family: List[Tuple[int, ...]], n: int, k: int) -> bool:
    if len(family) < comb(k, n):
        return True  # hypothesis not met
    return comb(k, n - 1) <= len(shadow(family))
